"""Validation driver for BrickSchema__Brick__handle_extensions.py__<module>_1.

The region is a whole script: it parses "Brick.ttl" and every "extensions/*.ttl"
from the current directory, rewrites the graph, and writes
"Brick+extensions.ttl".  Brick.ttl is generated by generate_brick.py and is not
in the repository, so the driver stages a working directory from the fixtures
next to this file and runs the script there.

Each side (the two artefacts RDFEVAL_SIDES names) runs in its OWN freshly
staged directory, with identical inputs and identical file names.  Two sides
sharing one directory would overwrite each other's "Brick+extensions.ttl" and
the comparison below would read one file twice.  Nothing is written back into
the example directory.

What is compared (module-state oracle, as run_pair does, plus the file):

  * every module-level graph (here `brick_graph`), by RDF isomorphism;
  * every module-level value both sides define (loop variables, `BRICK`...);
  * printed output;
  * the FILE the region writes -- its last and only external effect, which
    run_pair cannot see.  Per side, the written "Brick+extensions.ttl" is
      - present (a region that stops writing it fails),
      - parsed back as Turtle and compared by RDF isomorphism with the other
        side's file (a lost or extra triple in the *serialised* graph fails),
      - compared on its `@prefix` declarations (the set of prefix lines: what
        `@graph` / `@graph as` must not change),
      - compared on its ending (`.rstrip()` then exactly one "\\n": a missing
        or doubled newline fails),
      - and compared as a multiset of Turtle tokens, order and layout aside
        (rdflib orders blank nodes by their random labels, so the very same
        script writes its `sh:declare [ ... ]` blocks in a different order,
        with different `,` `;` `[` `]` placement, on each run; the terms
        themselves do not change).
    It must also be non-trivial: the original side's file holds triples, so a
    pair that both write an empty file cannot pass.
"""
import contextlib
import os
import re
import shutil
import tempfile
import traceback
from pathlib import Path

from rdflib import Graph

from rdfeval.harness import (
    _compare_value, _emit, _exec_ldpy, _exec_python, _graphs, _values,
    graphs_isomorphic,
)

HERE = Path(__file__).resolve().parent
WRITTEN = "Brick+extensions.ttl"


def run_side(runner, artefact: Path):
    """Run one artefact in its own staged directory.

    Returns (namespace, stdout, written file text or None), the directory
    having been removed.
    """
    work = Path(tempfile.mkdtemp(prefix="brick-handle-extensions-"))
    previous = Path.cwd()
    try:
        shutil.copy(HERE / "fixture.ttl", work / "Brick.ttl")
        shutil.copytree(HERE / "extensions_fixture", work / "extensions")
        os.chdir(work)
        ns, out = runner(artefact)
        written = work / WRITTEN
        text = written.read_bytes().decode("utf-8") if written.exists() else None
        return ns, out, text
    finally:
        os.chdir(previous)
        shutil.rmtree(work, ignore_errors=True)


def prefix_lines(text: str) -> list[str]:
    return sorted(line for line in text.splitlines() if line.startswith("@prefix"))


def token_multiset(text: str) -> list[str]:
    """The file's Turtle tokens, order and punctuation aside."""
    tokens = re.findall(r'"(?:[^"\\]|\\.)*"(?:\^\^\S+)?|[^\s\[\],;]+', text)
    return sorted(t for t in tokens if t != ".")


def main() -> dict:
    verdict: dict = {"example": HERE.name, "equivalent": False,
                     "method": "custom:module-state+written-file",
                     "diffs": [], "error": None}
    try:
        ns_o, out_o, file_o = run_side(_exec_python, HERE / "original.py")
        ns_t, out_t, file_t = run_side(_exec_ldpy, HERE / "translated.ldpy")
    except Exception:
        verdict["error"] = traceback.format_exc(limit=8)
        _emit(verdict)
        return verdict

    diffs: list[str] = []

    # module state, as run_pair compares it
    go, gt = _graphs(ns_o), _graphs(ns_t)
    if set(go) != set(gt):
        diffs.append(f"graph variables differ: {sorted(go)} vs {sorted(gt)}")
    for name in sorted(set(go) & set(gt)):
        _compare_value(go[name], gt[name], f"graph {name}", diffs)
    vo, vt = _values(ns_o), _values(ns_t)
    for name in sorted(set(vo) & set(vt)):
        _compare_value(vo[name], vt[name], f"value {name}", diffs, True)
    if out_o != out_t:
        diffs.append("stdout differs")
    verdict["graphs_compared"] = sorted(set(go) & set(gt))
    verdict["values_compared"] = sorted(set(vo) & set(vt))

    # the file each side wrote
    if file_o is None or file_t is None:
        diffs.append(f"{WRITTEN} not written by "
                     f"{'original' if file_o is None else 'translated'} side"
                     if (file_o is None) != (file_t is None) else
                     f"{WRITTEN} not written by either side")
    else:
        try:
            parsed_o = Graph().parse(data=file_o, format="turtle")
            parsed_t = Graph().parse(data=file_t, format="turtle")
        except Exception as e:
            diffs.append(f"{WRITTEN} does not parse back as Turtle: {e}")
        else:
            if len(parsed_o) == 0:
                diffs.append(f"{WRITTEN} of the original side is empty: "
                             "nothing to compare")
            if not graphs_isomorphic(parsed_o, parsed_t):
                diffs.append(f"{WRITTEN}: written graphs not isomorphic "
                             f"({len(parsed_o)} vs {len(parsed_t)} triples)")
        if prefix_lines(file_o) != prefix_lines(file_t):
            diffs.append(f"{WRITTEN}: @prefix lines differ "
                         f"({prefix_lines(file_o)} vs {prefix_lines(file_t)})")
        for side, text in (("original", file_o), ("translated", file_t)):
            if not text.endswith("\n") or text.endswith("\n\n"):
                diffs.append(f"{WRITTEN} ({side}) does not end in exactly one newline")
        if token_multiset(file_o) != token_multiset(file_t):
            diffs.append(f"{WRITTEN}: Turtle tokens differ (order aside)")
        verdict["written_triples"] = len(Graph().parse(data=file_o, format="turtle")) \
            if file_o else 0

    verdict["diffs"] = diffs
    verdict["equivalent"] = not diffs
    _emit(verdict)
    return verdict


VERDICT = main()
